theorem threshold_persistence {f : ℝ → ℝ} {t t₀ threshold δ L : ℝ}
    (hi : f t₀≤threshold-δ) (hb : |f t-f t₀|≤L*|t-t₀|)
    (hs : L*|t-t₀|<δ) : f t<threshold

theorem region_disagreement_subset {α : Type*} (ρ ω ρ' ω' : α → ℝ) (a b : ℝ)
    (j : Fin 3) : region ρ ω a b j ∆ region ρ' ω' a b j ⊆
      {x | label (ρ x) (ω x) a b≠label (ρ' x) (ω' x) a b}

theorem label_measurable {α : Type*} [MeasurableSpace α] {ρ ω : α → ℝ}
    (hr : Measurable ρ) (hl : Measurable ω) (a b : ℝ) :
    Measurable (fun x => label (ρ x) (ω x) a b)

theorem region_measurable {α : Type*} [MeasurableSpace α] {ρ ω : α → ℝ}
    (hr : Measurable ρ) (hl : Measurable ω) (a b : ℝ) (j : Fin 3) :
    MeasurableSet (region ρ ω a b j)

theorem jacobian_eq (ε x y z : ℝ) :
    jacobian ε x y z=!![-2*ε*x*profile x y*Real.cos z, -2*ε*y*profile x y*Real.cos z,
      -ε*profile x y*Real.sin z;
     -2*ε*x*profile x y*Real.sin z, -2*ε*y*profile x y*Real.sin z, ε*profile x y*Real.cos z;
     -2*x*profile x y, -2*y*profile x y, 0]

theorem actualLaplacian_eq {P Dx Dy Dxx Dyy : ℝ × ℝ → ℝ}
    (h : PressureDomain P Dx Dy Dxx Dyy) (x : ℝ × ℝ) :
    actualLaplacian P x=Dxx x+Dyy x

theorem response_actual_laplacian {P Dx Dy Dxx Dyy : ℝ × ℝ → ℝ}
    (h : PressureDomain P Dx Dy Dxx Dyy) :
    physicalResponse (pressureL2 h)=(1/8 : ℝ)*(∫ x, actualLaplacian P x ∂physicalGaussian)

theorem harmonic_response_zero {P Dx Dy Dxx Dyy : ℝ × ℝ → ℝ}
    (h : PressureDomain P Dx Dy Dxx Dyy) (hh : ∀ x, actualLaplacian P x=0) :
    physicalResponse (pressureL2 h)=0

theorem response_negative_iff {P Dx Dy Dxx Dyy : ℝ × ℝ → ℝ}
    (h : PressureDomain P Dx Dy Dxx Dyy) :
    physicalResponse (pressureL2 h)<0 ↔ (∫ x, actualLaplacian P x ∂physicalGaussian)<0

theorem response_derivative_duality {p : GaussianL2} {g : GaussianVectorL2}
    (hp : (p,g) ∈ closedCylindricalDerivative.graph) :
    response p=inner ℝ g (recovery radialTarget)

theorem physicalResponse_derivative_duality (p : PhysicalL2) {g : GaussianVectorL2}
    (hp : (physicalPullback p,g) ∈ closedCylindricalDerivative.graph) :
    physicalResponse p=inner ℝ g (recovery radialTarget)
